) AS v(id, lift_code, months_ago, day_offset, open_days, category, priority,
       cost, title, remark, reopen, inspector_id)
JOIN lifts l ON l.lift_code = v.lift_code
CROSS JOIN LATERAL (
  SELECT x.ts AS closed_ts,
         x.ts - make_interval(days => v.open_days) AS raised_ts
    FROM (
      SELECT date_trunc('month', CURRENT_DATE)
             - make_interval(months => v.months_ago)
             + make_interval(days => v.day_offset)
             + INTERVAL '11 hours' AS ts
    ) x
) t
ON CONFLICT (id) DO NOTHING;
